/////////////////////////////////////////////////////////////////////
// FUNCTION:a set of 4 sine waves is inputted to the FFT processor,
//          the results are compared with the expected waves,
//          the square root mean error is calculated (without a root)
// FILES:   USFFT64_2B_TB.v - this file, contains
//	      USFFT64_2B.v - unit under test
//          sin_tst_rom.v - rom with the test waveform, generating by 
//          sinerom64_gen.pl   
//  PROPERTIES: 1) the calculated error after ca. 4us modeling 
//		is outputted to the console	 as the note:
//   	      rms error is           1 lsb
//		2)if the error is 0,1,2 then the test is OK
//		3) the customer can exchange the test selecting the 
//		different frequencies and generating the wave ROM by
//          the script  sinerom64_gen.pl   		 	
//		4) the proper operation can be checked by investigation
//          of the core output waveforms
/////////////////////////////////////////////////////////////////////
`include "fft64_config.inc"	 

`timescale 1ns / 1ps
module USFFT64_2B_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;

	//Parameters declaration: 
	//defparam UUT.nb = 12;
	`USFFT64paramnb	

	//Internal signals declarations:
	reg CLK;
	reg RST;
	reg ED;
	reg START;
	reg [3:0]SHIFT;
	wire [nb-1:0]DR;
	wire [nb-1:0]DI;
	wire RDY;
	wire OVF1;
	wire OVF2;
	wire [5:0]ADDR;
	wire signed [nb+2:0]DOR;
	wire signed [nb+2:0]DOI;		 

	initial begin
			CLK = 1'b0;
			forever #5 CLK = ~CLK;
		end
	initial begin	
			SHIFT = 4'b0000;
			ED = 1'b1;
			RST = 1'b0;
			START = 1'b0;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

			#13 RST =1'b1;
			#43 RST =1'b0;
			#53 START =1'b1;
			#12 START =1'b0;
		end	  

	reg [5:0] ct64;
	always @(posedge CLK or posedge START) begin
			if (START) ct64 = 6'b000000;
			else ct64 = ct64 + 'd1;
		end

	wire [15:0] DATA_RE,DATA_IM,DATA_0;	
	Wave_ROM64 UG( .ADDR(ct64) ,
		.DATA_RE(DATA_RE), .DATA_IM(DATA_IM), .DATA_REF(DATA_0) );// 

	assign DR=DATA_RE[15:15-nb+1];
	assign DI=DATA_IM[15:15-nb+1];

	// Unit Under Test 
	USFFT64_2B UUT (
		.CLK(CLK),
		.RST(RST),
		.ED(ED),
		.START(START),
		.SHIFT(SHIFT),
		.DR(DR),
		.DI(DI),
		.RDY(RDY),
		.OVF1(OVF1),
		.OVF2(OVF2),
		.ADDR(ADDR),
		.DOR(DOR),
		.DOI(DOI));

		wire [5:0] addrr;		  
	`ifdef USFFT64paramifft
		assign addrr= (64-ADDR);  //the result order if IFFT 
	`else  
		assign addrr= ADDR;
	`endif


		wire signed [15:0] DATA_R0,DATA_I0,DATA_REF;	
	Wave_ROM64 UR( .ADDR(addrr) ,
		.DATA_RE(DATA_R0), .DATA_IM(DATA_I0), .DATA_REF(DATA_REF) );// 

	wire signed [18:15-nb+1] DREF=2*DATA_REF[15:15-nb+1];

	integer sqra; 
	integer ctres; 
	reg f;				  
	initial f=0;
	always@(posedge CLK) begin 
		if (f) 
			ctres=ctres+1;
			if (RST || RDY)  begin
				if (RDY) begin
					f=1;
					$fclose(file_mantra);
					$finish;				
				end
				sqra=0;
				ctres=0; end
			else if (ctres<64) begin
					#2 sqra = sqra +(DREF-DOR)*(DREF-DOR);
				#2 sqra = sqra +(DOI)*(DOI); end		 
			else if (ctres==64)  begin
				$display("rms error is ", (sqra/128), " lsb");

				end
		end

	///////////////////added
	integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      // $fwrite(file_mantra, "RDY,");
      // $fwrite(file_mantra, "OVF1,");
      // $fwrite(file_mantra, "OVF2,");
      // $fwrite(file_mantra, "DOR,");
      $fwrite(file_mantra, "DOI,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        // $fwrite(file_mantra, "%h, ", RDY);
        // $fwrite(file_mantra, "%h, ", OVF1);
        // $fwrite(file_mantra, "%h, ", OVF2);
        // $fwrite(file_mantra, "%h, ", DOR);
        $fwrite(file_mantra, "%h, ", DOI);

            $fwrite(file_mantra, "\n");
          end
        end
        initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        #2000
        $finish;

        end



// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST


    // 2. THEN WAIT for original tests
    // The synchronization signal ensures we run before the original testbench logic starts
    wait(llm_go_signal == 1);

    $display("LLM: Starting Mutation Testing Stimuli...");

    // Initialize Signals
    // RST is active high in this design
    RST = 1;
    ED = 1;
    START = 0;
    SHIFT = 4'b0000;

    // Force wires that are driven by assigns in the original TB
    // We must use force because DR and DI are wires driven by continuous assignment
    force DR = 16'h0000;
    force DI = 16'h0000;

    // Reset Sequence
    #100;
    @(posedge CLK);
    RST = 0;
    #20;
    @(posedge CLK);
    RST = 1; // Active High Reset
    #20;
    @(posedge CLK);
    RST = 0;

    // ---------------------------------------------------------
    // Test Case 1: Impulse Response (Dirac Delta)
    // Input: Single magnitude at index 0, zeros elsewhere.
    // Expected Output: Flat magnitude spectrum (constant value across all bins).
    // Kills: Coefficient mutations, connectivity faults.
    // ---------------------------------------------------------
    $display("LLM: Test Case 1 - Impulse Response");
    @(posedge CLK);
    START = 1;
    force DR = 16'h2000; // Impulse Magnitude
    force DI = 16'h0000;

    @(posedge CLK);
    START = 0;

    for (i = 1; i < 64; i = i + 1) begin
        force DR = 16'h0000;
        force DI = 16'h0000;
        @(posedge CLK);
    end

    // Wait for pipeline to flush (approx 150 cycles for 64-point FFT + buffers)
    repeat(150) @(posedge CLK);

    // ---------------------------------------------------------
    // Test Case 2: DC Input (Constant)
    // Input: Constant value across all 64 samples.
    // Expected Output: Peak at bin 0, near zero elsewhere.
    // Kills: Adder mutations, butterfly structure faults.
    // ---------------------------------------------------------
    $display("LLM: Test Case 2 - DC Input");
    @(posedge CLK);
    START = 1;
    force DR = 16'h1000;
    force DI = 16'h0000;

    @(posedge CLK);
    START = 0;

    for (i = 1; i < 64; i = i + 1) begin
        force DR = 16'h1000;
        force DI = 16'h0000;
        @(posedge CLK);
    end

    repeat(150) @(posedge CLK);

    // ---------------------------------------------------------
    // Test Case 3: Nyquist Frequency (Alternating)
    // Input: +A, -A, +A, -A...
    // Expected Output: Peak at bin 32 (Nyquist).
    // Kills: Frequency mapping faults, twiddle factor addressing faults.
    // ---------------------------------------------------------
    $display("LLM: Test Case 3 - Nyquist Frequency");
    @(posedge CLK);
    START = 1;
    force DR = 16'h1000;
    force DI = 16'h0000;

    @(posedge CLK);
    START = 0;

    for (i = 1; i < 64; i = i + 1) begin
        if (i % 2 != 0) // Odd indices
            force DR = 16'hF000; // Negative value (approx -4096)
        else
            force DR = 16'h1000; // Positive value (4096)
        force DI = 16'h0000;
        @(posedge CLK);
    end

    repeat(150) @(posedge CLK);

    // ---------------------------------------------------------
    // Test Case 4: Overflow Trigger (SHIFT = 0)
    // Input: Large values with no scaling (SHIFT=0).
    // Expected Output: OVF1 or OVF2 signals should assert.
    // Kills: CNORM logic mutations, overflow detection faults.
    // ---------------------------------------------------------
    $display("LLM: Test Case 4 - Overflow Trigger");
    SHIFT = 4'b0000;
    @(posedge CLK);
    START = 1;
    force DR = 16'h7000; // Large positive value
    force DI = 16'h7000;

    @(posedge CLK);
    START = 0;

    for (i = 1; i < 64; i = i + 1) begin
        force DR = 16'h7000;
        force DI = 16'h7000;
        @(posedge CLK);
    end

    repeat(150) @(posedge CLK);

    // ---------------------------------------------------------
    // Test Case 5: Overflow Prevention (SHIFT = Max)
    // Input: Same large values but with max scaling (SHIFT=1111).
    // Expected Output: OVF signals should NOT assert (or be reduced).
    // Kills: Shifter logic mutations.
    // ---------------------------------------------------------
    $display("LLM: Test Case 5 - Overflow Prevention");
    SHIFT = 4'b1111; // Max shift for both stages
    @(posedge CLK);
    START = 1;
    force DR = 16'h7000;
    force DI = 16'h7000;

    @(posedge CLK);
    START = 0;

    for (i = 1; i < 64; i = i + 1) begin
        force DR = 16'h7000;
        force DI = 16'h7000;
        @(posedge CLK);
    end

    repeat(150) @(posedge CLK);

    // ---------------------------------------------------------
    // Test Case 6: Enable Toggle (Pipeline Stall)
    // Input: Standard wave, but toggle ED (Enable) mid-stream.
    // Expected Output: Valid output delayed by stall duration.
    // Kills: Pipeline register enable faults, control flow mutations.
    // ---------------------------------------------------------
    $display("LLM: Test Case 6 - Enable Toggle");
    SHIFT = 4'b0000;
    @(posedge CLK);
    START = 1;
    force DR = 16'h2000;
    force DI = 16'h0000;

    @(posedge CLK);
    START = 0;

    for (i = 1; i < 64; i = i + 1) begin
        force DR = 16'h2000;
        force DI = 16'h0000;
        @(posedge CLK);

        // Stall for 5 cycles at index 32
        if (i == 32) begin
            ED = 0;
            repeat(5) @(posedge CLK);
            ED = 1;
        end
    end

    repeat(150) @(posedge CLK);

    // 4. Cleanup
    $display("LLM: Tests Finished. Handing over to Original TB...");

    // Release forced wires so original TB can drive them via its Wave_ROM64
    release DR;
    release DI;

    // Reset control signals to idle state expected by original TB
    RST = 0;
    ED = 1;
    START = 0;
    SHIFT = 0;

    // Handover control to the original testbench
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

